"""Reviewed adaptations of ten supplied grade-four social papers.
Preserve original source locators; graph values become complete textual data.
No official answer key was supplied. Re-run from repository root.
"""
import json
from pathlib import Path
rows=[]
def add(n,loc,prompt,options,answer=0,explanation='',page=1,passage=None):
 if isinstance(options,str):options=options.split('|')
 assert len(set(options))==len(options)
 correct=options[answer];shift=len(rows)%len(options);options=options[shift:]+options[:shift]
 r=dict(id=f'soc1-ksn{n}-{loc}',sourceId=f'ksn{n}',locator=loc,page=page,kind='題意整理轉選擇',prompt=prompt,options=options,answer=options.index(correct),hint='先確認題目條件，再比較地圖、自然環境或器物的用途。',explanation=explanation or f'依題意應選「{correct}」。')
 if passage:r['passage']=passage
 rows.append(r)
def tf(n,loc,p,correct,ex,page=1):add(n,loc,p+'這個說法正確嗎？','正確|不正確',0 if correct else 1,ex,page)
